/* Moniteur JSB — échantillons WAV masterisés (22 050 Hz, mono).
 * Cinq signaux proviennent d'enregistrements CC0 réadaptés; autres tonalités conçues par JSB. Voir AUDIO_CREDITS.md.
 * Les fichiers sont embarqués pour fonctionner hors ligne sur iOS et le web.
 */
(function(root){'use strict';
 const WAV=Object.freeze({
  "buzzerPro":"",
  "bellSport":"",
  "whistlePro":"",
  "hornPro":"",
  "digitalDuo":"",
  "wood":"",
  "pulse":"",
  "soft":"",
  "finishBell":"",
  "finishChime":"",
  "finishTriple":"",
  "countdown":""
 });
 const api=Object.freeze({
  ids:Object.freeze(Object.keys(WAV)),
  getWavBase64(id){return WAV[id]||null},
  getWavBytes(id){
   const encoded=WAV[id];if(!encoded)return null;
   const binary=typeof atob==='function'?atob(encoded):null;
   if(!binary)return null;
   const bytes=new Uint8Array(binary.length);
   for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
   return bytes;
  }
 });
 if(typeof module!=='undefined'&&module.exports)module.exports=api;
 root.JSBRealSignals=api;
})(typeof window!=='undefined'?window:globalThis);
